Build a complete website for the following brief with layout: split_hero.

<content_brief>
  <business_name>Apex Advisory Partners</business_name>
  <tagline>Modern Fractional CFO and Tax Strategy for Scale</tagline>
  <business_type>accounting</business_type>
  <layout_archetype>split_hero</layout_archetype>
  <layout_guidelines>50/50 split-screen hero layout with prominent brand typography and CTA on the left, paired with an interactive visual sandbox/widget on the right.</layout_guidelines>
  <motion_guidelines>Split Hero Motion: Implement coordinated asymmetric entrance with offset delays (left brand text at 0ms, right interactive visual widget at 160ms). Mandatory reduced-motion fallback: @media (prefers-reduced-motion: reduce) { .split-hero__left, .split-hero__right { opacity: 1 !important; transform: none !important; animation: none !important; } }</motion_guidelines>
  <primary_color>#0a1322</primary_color>
  <accent_color>#38bdf8</accent_color>
  <font_heading>Plus Jakarta Sans</font_heading>
  <font_body>Inter</font_body>
  <sections>header, hero, services, footer</sections>
  <item name="Fractional CFO & Runway Modeling" tag="Strategic" description="Multi-scenario cash burn forecasting, capital allocation roadmaps, and investor board deck preparation." />
  <item name="R&D Tax Credit Optimization" tag="Tax" description="Maximizing federal and state research incentives to reclaim up to $250k annually against payroll taxes." />
  <item name="Automated Cloud Accounting" tag="Operations" description="Full QuickBooks and NetSuite migration with automated Stripe reconciliation and multi-currency ledgers." />
  <item name="SOC 1 & GAAP Audit Prep" tag="Compliance" description="Rigorous balance sheet substantiation, revenue recognition (ASC 606), and external auditor management." />
  <contact>
    <address>111 W Washington St, Suite 1800, Chicago, IL 60602</address>
    <phone>+1 (312) 555-0188</phone>
    <email>partners@apexadvisorycfo.com</email>
    <hours>Mon–Fri: 8:30am–5:30pm CST</hours>
  </contact>
</content_brief>

You will build the site ONE SECTION AT A TIME. Start with the first section now.

FIRST SECTION REQUIRED: Write the Header section: a sticky navigation bar with the business name/logo on the left, navigation links (Home, Advisory Capabilities, Contact) on the right, plus 'Request Audit' CTA button. Files: src/components/Header.tsx + src/components/Header.css

Previous assistant implementation (context only):
<tool_call name="write_site">
<file path="src/components/Hero.tsx">
import React from 'react';
import './Hero.css';

export function Hero() {
  return (
    <section className="aa-hero aa-hero--split" id="hero" aria-labelledby="aa-hero-title">
      <div className="aa-hero__inner">
        <div className="aa-hero__left">
          <div className="aa-hero__badge">
            <span className="aa-hero__badge-pulse" aria-hidden="true" />
            <span>Apex Advisory Partners Platform</span>
          </div>

          <h1 id="aa-hero-title" className="aa-hero__title">
            Modern Fractional CFO and Tax Strategy for Scale
          </h1>

          <p className="aa-hero__subtitle">
            Empowering Series A through C technology founders with automated real-time financial models, R&D tax credit capture, and Board audit readiness.
          </p>

          <div className="aa-hero__actions">
            <a href="mailto:partners@apexadvisorycfo.com" className="aa-hero__btn-primary">
              Request Audit
            </a>
            <a href="#services" className="aa-hero__btn-secondary">
              Explore Advisory Capabilities
            </a>
          </div>
        </div>

        <div className="aa-hero__right">
          <div className="aa-hero__backdrop" aria-hidden="true" />
          <div className="aa-hero__card">
            <div className="aa-hero__card-header">
              <span className="aa-hero__card-dot" />
              <span className="aa-hero__card-dot" />
              <span className="aa-hero__card-dot" />
              <span className="aa-hero__card-status">LIVE SYSTEM ACTIVE</span>
            </div>
            <div className="aa-hero__card-body">
              <p className="aa-hero__card-title">Fractional CFO & Runway Modeling</p>
              <p className="aa-hero__card-desc">Multi-scenario cash burn forecasting, capital allocation roadmaps, and investor board deck preparation.</p>
              <div className="aa-hero__card-stat">
                <span className="aa-hero__card-tag">Strategic</span>
                <span className="aa-hero__card-metric">Optimized</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}

</file>
<file path="src/components/Hero.css">
.aa-hero {
  position: relative;
  min-height: 86vh;
  display: flex;
  align-items: center;
  background: #0a1322;
  overflow: hidden;
  padding: 5rem 2rem;
}

.aa-hero__inner {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: 4rem;
  align-items: center;
  position: relative;
  z-index: 1;
}

.aa-hero__badge {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.35rem 1rem;
  background: rgba(56, 189, 248, 0.08);
  border: 1px solid rgba(56, 189, 248, 0.22);
  border-radius: 999px;
  color: #e4e4e7;
  font-size: 0.82rem;
  font-weight: 500;
  margin-bottom: 1.5rem;
}

.aa-hero__badge-pulse {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #38bdf8;
  box-shadow: 0 0 8px #38bdf8;
}

.aa-hero__title {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-size: clamp(2.2rem, 4.5vw, 3.6rem);
  font-weight: 800;
  color: #fafafa;
  line-height: 1.14;
  letter-spacing: -0.02em;
  margin: 0 0 1.5rem;
}

.aa-hero__subtitle {
  font-size: 1.1rem;
  color: #a1a1aa;
  line-height: 1.7;
  margin: 0 0 2.2rem;
}

.aa-hero__actions {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}

.aa-hero__btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.85rem 2rem;
  background: #38bdf8;
  color: #0c0d12;
  font-weight: 700;
  font-size: 0.95rem;
  text-decoration: none;
  border-radius: 8px;
  transition: all 0.2s ease;
}

.aa-hero__btn-primary:hover {
  background: #0284c7;
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(56, 189, 248, 0.35);
}

.aa-hero__btn-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.85rem 2rem;
  background: rgba(56, 189, 248, 0.04);
  color: #fafafa;
  border: 1px solid rgba(56, 189, 248, 0.32);
  font-weight: 600;
  font-size: 0.95rem;
  text-decoration: none;
  border-radius: 8px;
  transition: all 0.2s ease;
}

.aa-hero__btn-secondary:hover {
  border-color: #38bdf8;
  color: #38bdf8;
  transform: translateY(-2px);
}

.aa-hero__right {
  position: relative;
}

.aa-hero__backdrop {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 420px;
  height: 420px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(56, 189, 248, 0.24) 0%, transparent 70%);
  filter: blur(32px);
  pointer-events: none;
}

.aa-hero__card {
  position: relative;
  background: #132138;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 14px;
  padding: 2rem;
  box-shadow: 0 20px 48px rgba(0, 0, 0, 0.4);
}

.aa-hero__card-header {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  margin-bottom: 1.5rem;
  padding-bottom: 1rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.aa-hero__card-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.2);
}

.aa-hero__card-status {
  margin-left: auto;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: #38bdf8;
}

.aa-hero__card-title {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-size: 1.35rem;
  font-weight: 700;
  color: #fafafa;
  margin: 0 0 0.75rem;
}

.aa-hero__card-desc {
  font-size: 0.95rem;
  color: #a1a1aa;
  line-height: 1.6;
  margin: 0 0 1.5rem;
}

.aa-hero__card-stat {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.aa-hero__card-tag {
  padding: 0.25rem 0.75rem;
  background: rgba(255, 255, 255, 0.06);
  border-radius: 6px;
  color: #38bdf8;
  font-size: 0.8rem;
  font-weight: 600;
}

.aa-hero__card-metric {
  color: #fafafa;
  font-size: 0.85rem;
  font-weight: 600;
}

@media (max-width: 900px) {
  .aa-hero__inner { grid-template-columns: 1fr; gap: 3rem; }
}

.aa-hero__left {
  animation: aaHeroLeftEnter 0.6s cubic-bezier(0.16, 1, 0.3, 1) 0ms both;
}

.aa-hero__right {
  animation: aaHeroRightEnter 0.6s cubic-bezier(0.16, 1, 0.3, 1) 160ms both;
}

@keyframes aaHeroLeftEnter {
  from { opacity: 0; transform: translateY(14px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes aaHeroRightEnter {
  from { opacity: 0; transform: translateY(14px); }
  to { opacity: 1; transform: translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
  .aa-hero__left,
  .aa-hero__right,
  .aa-hero__btn-primary,
  .aa-hero__btn-secondary {
    animation: none !important;
    transition: none !important;
    transform: none !important;
    opacity: 1 !important;
  }
}

</file>
</tool_call>

