<file path="src/components/Hero.css">
.sp-hero {
  position: relative;
  min-height: 86vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #0a111a;
  overflow: hidden;
  padding: 5rem 2rem;
}

.sp-hero__atmosphere {
  position: absolute;
  top: 10%;
  left: 50%;
  transform: translateX(-50%);
  width: 750px;
  height: 500px;
  border-radius: 50%;
  background: radial-gradient(ellipse at center, rgba(233, 170, 18, 0.16) 0%, transparent 70%);
  pointer-events: none;
  filter: blur(24px);
}

.sp-hero__inner {
  position: relative;
  z-index: 1;
  max-width: 880px;
  margin: 0 auto;
  text-align: center;
}

.sp-hero__badge {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.35rem 1rem;
  background: rgba(233, 170, 18, 0.08);
  border: 1px solid rgba(233, 170, 18, 0.22);
  border-radius: 999px;
  color: #e4e4e7;
  font-size: 0.82rem;
  font-weight: 500;
  margin-bottom: 1.5rem;
}

.sp-hero__badge-pulse {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #e9aa12;
  box-shadow: 0 0 8px #e9aa12;
}

.sp-hero__title {
  font-family: 'Inter', sans-serif;
  font-size: clamp(2.4rem, 5.5vw, 4.2rem);
  font-weight: 800;
  color: #fafafa;
  line-height: 1.12;
  letter-spacing: -0.02em;
  margin: 0 0 1.5rem;
}

.sp-hero__subtitle {
  font-size: 1.15rem;
  color: #a1a1aa;
  line-height: 1.7;
  max-width: 640px;
  margin: 0 auto 2.5rem;
}

.sp-hero__actions {
  display: flex;
  gap: 1rem;
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: 3rem;
}

.sp-hero__btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.85rem 2.2rem;
  background: #e9aa12;
  color: #0c0d12;
  font-weight: 700;
  font-size: 0.95rem;
  text-decoration: none;
  border-radius: 8px;
  transition: all 0.2s ease;
}

.sp-hero__btn-primary:hover {
  background: #ca8a04;
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(233, 170, 18, 0.35);
}

.sp-hero__btn-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.85rem 2.2rem;
  background: rgba(233, 170, 18, 0.04);
  color: #fafafa;
  border: 1px solid rgba(233, 170, 18, 0.32);
  font-weight: 600;
  font-size: 0.95rem;
  text-decoration: none;
  border-radius: 8px;
  transition: all 0.2s ease;
}

.sp-hero__btn-secondary:hover {
  border-color: #e9aa12;
  color: #e9aa12;
  transform: translateY(-2px);
}

.sp-hero__metrics {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
  max-width: 640px;
  margin: 0 auto;
  padding-top: 2rem;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}

.sp-hero__metric {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.sp-hero__metric-value {
  font-family: 'Inter', sans-serif;
  font-size: 1.6rem;
  font-weight: 700;
  color: #fafafa;
}

.sp-hero__metric-label {
  font-size: 0.8rem;
  color: #71717a;
}

@media (max-width: 600px) {
  .sp-hero__metrics { grid-template-columns: 1fr; gap: 1rem; }
}

@media (prefers-reduced-motion: reduce) {
  .sp-hero,
  .sp-hero__btn-primary,
  .sp-hero__btn-secondary,
  .sp-hero__atmosphere {
    animation: none !important;
    transition: none !important;
    transform: none !important;
  }
}

</file>
