import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`hsc-header${scrolled ? ' hsc-header--scrolled' : ''}`} role="banner">
      <div className="hsc-header__inner">
        <a href="#" className="hsc-header__logo" aria-label="Hyperion Serverless Home">
          Hyperion Serverless
        </a>

        <nav className="hsc-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="hsc-header__link">Home</a>
          <a href="#platform" className="hsc-header__link">Edge Platform</a>
          <a href="#footer" className="hsc-header__link">Contact</a>
        </nav>

        <div className="hsc-header__actions">
          <a href="mailto:sales@hyperioncloud.dev" className="hsc-header__cta">
            Start Free Trial
          </a>
          <button
            type="button"
            className="hsc-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="hsc-header__bar" />
            <span className="hsc-header__bar" />
            <span className="hsc-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="hsc-header__mobile-menu" role="dialog" aria-modal="true">
          <a href="#hero" className="hsc-header__mobile-link" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#platform" className="hsc-header__mobile-link" onClick={() => setMenuOpen(false)}>Edge Platform</a>
          <a href="#footer" className="hsc-header__mobile-link" onClick={() => setMenuOpen(false)}>Contact</a>
          <a href="mailto:sales@hyperioncloud.dev" className="hsc-header__mobile-cta" onClick={() => setMenuOpen(false)}>Start Free Trial</a>
        </div>
      )}
    </header>
  );
}
