import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`pcv-header${scrolled ? ' pcv-header--scrolled' : ''}`} role="banner">
      <div className="pcv-header__inner">
        <a href="#" className="pcv-header__logo" aria-label="Prism Computer Vision Home">
          Prism Computer Vision
        </a>

        <nav className="pcv-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="pcv-header__link">Home</a>
          <a href="#vision" className="pcv-header__link">Vision Capabilities</a>
          <a href="#footer" className="pcv-header__link">Contact</a>
        </nav>

        <div className="pcv-header__actions">
          <a href="mailto:industrial@prismvision.tech" className="pcv-header__cta">
            Request System Spec
          </a>
          <button
            type="button"
            className="pcv-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="pcv-header__bar" />
            <span className="pcv-header__bar" />
            <span className="pcv-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="pcv-header__mobile-menu" role="dialog" aria-modal="true">
          <a href="#hero" className="pcv-header__mobile-link" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#vision" className="pcv-header__mobile-link" onClick={() => setMenuOpen(false)}>Vision Capabilities</a>
          <a href="#footer" className="pcv-header__mobile-link" onClick={() => setMenuOpen(false)}>Contact</a>
          <a href="mailto:industrial@prismvision.tech" className="pcv-header__mobile-cta" onClick={() => setMenuOpen(false)}>Request System Spec</a>
        </div>
      )}
    </header>
  );
}
