import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`ler-header${scrolled ? ' ler-header--scrolled' : ''}`} role="banner">
      <div className="ler-header__inner">
        <a href="#" className="ler-header__logo" aria-label="L'Étoile Reserve Home">
          L'Étoile Reserve
        </a>

        <nav className="ler-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="ler-header__link">Home</a>
          <a href="#menu_sequences" className="ler-header__link">Tasting Sequences</a>
          <a href="#footer" className="ler-header__link">Contact</a>
        </nav>

        <div className="ler-header__actions">
          <a href="mailto:reservations@letoilereserve.fr" className="ler-header__cta">
            Reserve Tasting Table
          </a>
          <button
            type="button"
            className="ler-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="ler-header__bar" />
            <span className="ler-header__bar" />
            <span className="ler-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="ler-header__mobile-menu" role="dialog" aria-modal="true">
          <a href="#hero" className="ler-header__mobile-link" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#menu_sequences" className="ler-header__mobile-link" onClick={() => setMenuOpen(false)}>Tasting Sequences</a>
          <a href="#footer" className="ler-header__mobile-link" onClick={() => setMenuOpen(false)}>Contact</a>
          <a href="mailto:reservations@letoilereserve.fr" className="ler-header__mobile-cta" onClick={() => setMenuOpen(false)}>Reserve Tasting Table</a>
        </div>
      )}
    </header>
  );
}
